import { z } from "zod";

export const createNewUserSchema = z
  .object({
    first_name: z.string().min(1, "validation.required"),
    last_name: z.string().min(1, "validation.required"),
    email: z.string().min(1, "validation.required").email("validation.email_invalid"),
    phone_number: z.string().min(1, "validation.required"),
    password: z.string().min(1, "validation.required").min(8, "validation.password_min"),
    password_confirmation: z.string().min(1, "validation.required"),
    role_id: z.number({ message: "validation.required" }),
    user_type: z.string().optional(),
    developer_id: z.number().optional(),
    developer_role: z.string().optional(),
    status: z.enum(["active", "inactive", "banned"]).optional(),
    description: z.string().optional(),
    profile_picture: z.any().optional(),
  })
  .refine((data) => data.password === data.password_confirmation, {
    message: "validation.passwords_must_match",
    path: ["password_confirmation"],
  })
  .refine((data) => {
    if (data.user_type?.toLowerCase() === "developer") {
      return !!data.developer_id;
    }
    return true;
  }, {
    message: "validation.developer_required",
    path: ["developer_id"],
  })
  .refine((data) => {
    if (data.user_type?.toLowerCase() === "developer") {
      return !!data.developer_role;
    }
    return true;
  }, {
    message: "validation.developer_role_required",
    path: ["developer_role"],
  });

export type CreateNewUserInput = z.infer<typeof createNewUserSchema>;
